const sd  = $getWorkflowStaticData('global');
const msg = $json.message || $json;
const text   = (msg.text || msg.caption || '').trim();
const chatId = msg.chat?.id || sd.chatId || '';

// Store chat ID permanently
if (chatId && !sd.chatId) sd.chatId = chatId;

// Conversation history (last 8 messages)
if (!Array.isArray(sd.history)) sd.history = [];
sd.history.push({ role: 'user', content: text });
if (sd.history.length > 8) sd.history = sd.history.slice(-8);

// Build messages array for Claude (last 6 turns)
const messages = sd.history.slice(-6).map(h => ({ role: h.role, content: h.content }));

return [{ json: {
  chatId,
  userMessage: text,
  messages,
  lastJob: sd.lastAnalyzedJob || null,
} }];

const sd = $getWorkflowStaticData('global');
const raw = $json.content?.[0]?.text || $json.choices?.[0]?.message?.content || '';

let parsed;
try {
  // Strip any accidental markdown code fences
  const clean = raw.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = { intent: 'general', mode: 'friend', response: raw || 'Sorry, something went wrong. Try again.', structured: null };
}

// Store assistant reply in conversation history
if (!Array.isArray(sd.history)) sd.history = [];
sd.history.push({ role: 'assistant', content: parsed.response });
if (sd.history.length > 8) sd.history = sd.history.slice(-8);

// Persist last analyzed job for resume requests
if (parsed.intent === 'analyze_job' && parsed.structured) {
  sd.lastAnalyzedJob = parsed.structured;
}

// Log daily activity
const today = new Date().toDateString();
if (!sd.dailyActivity)          sd.dailyActivity = {};
if (!sd.dailyActivity[today])   sd.dailyActivity[today] = { analyzed: 0, applied: 0, lastActive: Date.now() };
if (parsed.intent === 'analyze_job') sd.dailyActivity[today].analyzed++;
if (parsed.intent === 'applied')     sd.dailyActivity[today].applied++;
sd.dailyActivity[today].lastActive = Date.now();

// Keep daily log for 30 days
const days = Object.keys(sd.dailyActivity);
if (days.length > 30) {
  const keep = days.sort().slice(-30);
  sd.dailyActivity = Object.fromEntries(keep.map(d => [d, sd.dailyActivity[d]]));
}

const chatId  = $('Process Message').item.json.chatId;
const lastJob = sd.lastAnalyzedJob || null;

return [{ json: { ...parsed, chatId, lastJob } }];

const sd  = $getWorkflowStaticData('global');
const job = $json.lastJob || sd.lastAnalyzedJob || {};

const company  = (job.company || 'Company').replace(/[^a-zA-Z0-9]/g,'_');
const role     = job.title    || 'SAP Consultant';
const keywords = (job.keywords || []).join(', ');
const applyLink = job.link    || null;
const expReq   = job.exp_required || 'Not specified';

// Build a targeted summary via Claude context
const tailoredSummary =
  `SAP Technical Consultant and AI Automation Engineer with 5+ years of hands-on ABAP and enterprise consulting experience. \
Expertise in ${keywords || 'SAP BTP, Integration, S/4HANA, OData, RICEF'}. \
Independently designed and deployed a production AI automation system (n8n + Claude API + Oracle Cloud, 24/7). \
Master's in Data Analytics, Indiana Wesleyan University (2025). Actively seeking H1B sponsorship.`;

const ctx = JSON.stringify({
  summary:    tailoredSummary,
  company:    job.company || 'Company',
  role:       role,
  keywords:   job.keywords || [],
  outputPath: `/tmp/HarshaYelamati_${company}.docx`,
});

return [{ json: {
  buildCmd:   `node /home/ubuntu/job-scripts/build_resume_dynamic.js '${ctx.replace(/'/g, "'\\''")}'`,
  outputPath: `/tmp/HarshaYelamati_${company}.docx`,
  company:    job.company || 'Company',
  role,
  keywords,
  applyLink,
  expReq,
  chatId: $json.chatId || sd.chatId,
} }];

const sd = $getWorkflowStaticData('global');
const { company, role, keywords, applyLink, expReq } = $json;
const applyLine = applyLink ? `\n🔗 Apply: ${applyLink}` : '';

const text = `📄 *Resume ready — ${role} @ ${company}*

✅ Summary tailored to: ${keywords || 'your target role'}
📋 Role: ${role}
⏳ Experience needed: ${expReq}${applyLine}

Send this .docx when applying. Good luck! 🙌`;

return [{ json: { text, chatId: $json.chatId || sd.chatId } }];

const sd = $getWorkflowStaticData('global');
const { structured, chatId } = $json;
const company = structured?.company || 'Unknown Company';
const role    = structured?.role    || 'Unknown Role';
const today   = new Date().toISOString().split('T')[0];

// Track for follow-up
if (!Array.isArray(sd.applications)) sd.applications = [];
sd.applications.push({ company, role, dateApplied: today, status: 'Applied' });

// Count week's applications
const weekAgo = new Date(); weekAgo.setDate(weekAgo.getDate() - 7);
const weekCount = sd.applications.filter(a => new Date(a.dateApplied) >= weekAgo).length;
const followUpDate = new Date(); followUpDate.setDate(followUpDate.getDate() + 7);
const followUpStr  = followUpDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });

const confirmText =
  `✅ *Logged!* ${role} @ ${company}\n\nApplied: Today (${today})\nFollow-up reminder: ${followUpStr}\n\nThis week: ${weekCount} application${weekCount !== 1 ? 's' : ''}. Keep going.`;

return [{ json: {
  chatId,
  text:        confirmText,
  rowData:     { company, role, dateApplied: today, status: 'Applied', source: 'Manual' },
} }];

const sd     = $getWorkflowStaticData('global');
const chatId = $json.chatId || sd.chatId;

const weekAgo  = new Date(); weekAgo.setDate(weekAgo.getDate() - 7);
const apps     = sd.applications || [];
const weekApps = apps.filter(a => new Date(a.dateApplied) >= weekAgo);
const total    = apps.length;
const pending  = apps.filter(a => a.status === 'Applied').length;
const interviews = apps.filter(a => a.status === 'Interview').length;

const today    = new Date().toDateString();
const todayAct = sd.dailyActivity?.[today] || { analyzed: 0, applied: 0 };

const text = `📊 *Your Job Search Status*

This week: ${weekApps.length} applications
All time: ${total} total

Pending response: ${pending}
Interviews: ${interviews}

Today: Applied ${todayAct.applied} | Analyzed ${todayAct.analyzed}

Recent applications:
${apps.slice(-5).reverse().map(a => `• ${a.role} @ ${a.company} (${a.status})`).join('\n') || 'None yet'}`;

return [{ json: { text, chatId } }];

const sd     = $getWorkflowStaticData('global');
const chatId = sd.chatId;
if (!chatId) return [];

// Get top 3 from digest queue (from job alert master workflow)
const queue = (sd.digestQueue || []).sort((a,b) => (b.score||0)-(a.score||0));
const top3  = queue.slice(0, 3);

// Clear shown jobs from queue
sd.digestQueue = queue.slice(3);

const today = new Date().toLocaleDateString('en-US', { weekday:'long', month:'short', day:'numeric' });
const greeting = new Date().getHours() < 10 ? 'Good morning' : 'Hey';

let body = '';
if (top3.length === 0) {
  body = 'No new top matches queued right now. New alerts fire every 30 min.';
} else {
  const icons = ['🟢','🟡','🟡','🟠'];
  body = top3.map((j, i) => {
    const icon  = j.score >= 7 ? '🟢' : j.score >= 5 ? '🟡' : '🟠';
    return `${i+1}. ${icon} *${j.title}* @ ${j.company || 'N/A'}\n    ⭐${j.score}/10 | ${j.source || ''}`;
  }).join('\n\n');
}

const text = `☀️ ${greeting}, Harsha. ${today}

${top3.length > 0 ? `Top ${top3.length} job${top3.length > 1 ? 's' : ''} for today:` : 'Today\'s jobs:'}

${body}

Paste any job description to analyze it, or say "resume" after analyzing to get your tailored CV.`;

return [{ json: { text, chatId } }];

const sd     = $getWorkflowStaticData('global');
const chatId = sd.chatId;
if (!chatId) return [];

const today    = new Date().toDateString();
const activity = sd.dailyActivity?.[today] || { analyzed: 0, applied: 0 };
const weekAgo  = new Date(); weekAgo.setDate(weekAgo.getDate() - 7);
const weekApps = (sd.applications || []).filter(a => new Date(a.dateApplied) >= weekAgo).length;

let mood = '';
if (activity.applied === 0) {
  mood = "⚡ *You didn't apply today. That's a day lost. Tomorrow — pick 2 jobs and apply. No delays.*";
} else if (activity.applied >= 3) {
  mood = "💪 Solid day. Consistency is what gets you hired.";
} else {
  mood = "Good progress. Keep the momentum.";
}

const text = `🌙 *End of day — ${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric'})}*

Today: Applied *${activity.applied}* | Analyzed *${activity.analyzed}*
This week: *${weekApps}* applications total

${mood}`;

return [{ json: { text, chatId } }];

const sd = $getWorkflowStaticData('global');
const chatId = sd.chatId;
if (!chatId) return [];

const apps = (sd.applications || []).filter(a => a.status === 'Applied');
const today = new Date();
const reminders = [];

for (const app of apps) {
  const applied = new Date(app.dateApplied);
  const daysAgo = Math.floor((today - applied) / 86400000);
  if (daysAgo === 7 || daysAgo === 14) {
    reminders.push(app);
  }
}

if (reminders.length === 0) return [];

return reminders.map(app => ({
  json: {
    chatId,
    company: app.company,
    role:    app.role,
    daysAgo: Math.floor((today - new Date(app.dateApplied)) / 86400000),
    text: `📬 *Follow-up reminder*

${app.role} @ ${app.company}
Applied ${Math.floor((today - new Date(app.dateApplied)) / 86400000)} days ago — no response yet.

💬 Suggested message:
_"Hi, I wanted to follow up on my application for the ${app.role} role. I remain very interested in this opportunity and would love to connect. Thank you for your time."_

Reply *"sent ${app.company}"* to mark as followed up.`,
  }
}));

const sd     = $getWorkflowStaticData('global');
const chatId = sd.chatId;
if (!chatId) return [];

const weekAgo = new Date(); weekAgo.setDate(weekAgo.getDate() - 7);
const apps    = (sd.applications || []).filter(a => new Date(a.dateApplied) >= weekAgo);
const total   = apps.length;

// Count by status
const interviews = apps.filter(a => a.status === 'Interview').length;
const responses  = apps.filter(a => a.status !== 'Applied').length;

// Days active this week
const activity = sd.dailyActivity || {};
const activeDays = Object.keys(activity).filter(d => {
  const dt = new Date(d);
  return dt >= weekAgo && (activity[d].applied > 0 || activity[d].analyzed > 0);
}).length;

let feedback = '';
if (total === 0)       feedback = "⚡ Zero applications this week. That needs to change. Pick 3 companies today and apply.";
else if (total < 5)    feedback = "Volume is low. Aim for 5+ per week minimum. Quality + quantity both matter.";
else if (total < 10)   feedback = "Good volume. Focus on SAP BTP and AI roles for highest match rate.";
else                   feedback = "Strong volume this week. Well done. Stay consistent.";

const topCompany = apps.length > 0 ? apps[apps.length - 1].company : 'N/A';

const text = `📊 *Weekly Review*

Applications: *${total}* | Responses: *${responses}* | Interviews: *${interviews}*
Active days: ${activeDays}/7
Most recent: ${topCompany}

${feedback}

Next week target: 5-8 applications. Focus: SAP BTP + Data Analyst + AI Automation roles.`;

return [{ json: { text, chatId } }];
